const items = $input.all();

function contains(value, term) {
  if (!value) return false;

  if (Array.isArray(value)) {
    return value.some(v =>
      String(v).toLowerCase().includes(term.toLowerCase())
    );
  }

  return String(value)
    .toLowerCase()
    .includes(term.toLowerCase());
}

const scored = items.map(item => {
  const event = item.json;

  let score = 0;
  const reasons = [];

  // Destaque editorial/manual
  if (event.featured === true) {
    score += 30;
    reasons.push("featured");
  }

  // Eventos grandes
  if (event.is_big_event === true) {
    score += 25;
    reasons.push("big_event");
  }

  // Evento principal
  if (event.level === "main") {
    score += 15;
    reasons.push("main_event");
  }

  // Conferências tendem a ter mais relevância para o Radar
  if (
    contains(event.event_type, "conference") ||
    contains(event.category, "conference")
  ) {
    score += 10;
    reasons.push("conference");
  }

  // Ter Olhar da Agenda já produzido é um sinal editorial forte
  if (
    event.agenda_highlight &&
    event.agenda_highlight.trim().length > 100
  ) {
    score += 20;
    reasons.push("agenda_highlight");
  }

  // Intenção comercial/networking
 if (
  contains(event.intent, "negocios") ||
  contains(event.intent, "business")
) {
  score += 8;
  reasons.push("business");
}

  if (contains(event.intent, "networking")) {
    score += 6;
    reasons.push("networking");
  }

  if (contains(event.intent, "institucional")) {
    score += 5;
    reasons.push("institutional");
  }

  // Diversidade LATAM
  if (
    event.country &&
    !["brazil", "brasil"].includes(
      event.country.toLowerCase()
    )
  ) {
    score += 5;
    reasons.push("latam");
  }

  // Imagem é importante para a newsletter
  if (event.image_url) {
    score += 3;
    reasons.push("image");
  }

  // Página/slug próprio na Agenda
  if (event.slug) {
    score += 3;
    reasons.push("agenda_page");
  }
 // Relevância direta para o ecossistema cripto
const coreCryptoTerms = [
  "crypto",
  "cripto",
  "blockchain",
  "web3",
  "bitcoin",
  "stablecoin",
  "defi",
  "token",
  "tokenização",
  "tokenization",
  "digital assets",
  "ativos digitais"
];

const adjacentTerms = [
  "payments",
  "pagamentos",
  "fintech"
];

const searchableContent = [
  event.title,
  event.description,
  event.short_description,
  event.category,
  event.event_type,
  event.tags
];

const hasCoreCrypto = coreCryptoTerms.some(term =>
  searchableContent.some(value => contains(value, term))
);

const hasAdjacent = adjacentTerms.some(term =>
  searchableContent.some(value => contains(value, term))
);

if (hasCoreCrypto) {
  score += 25;
  reasons.push("core_crypto_relevance");
} else if (hasAdjacent) {
  score += 5;
  reasons.push("adjacent_crypto_relevance");
} else {
  score -= 25;
  reasons.push("low_crypto_relevance");
}

  return {
    json: {
      ...event,
      radar_score: score,
      radar_score_reasons: reasons,
      agenda_url: event.slug
        ? `https://www.agendacryptoo.com/agenda/${event.slug}`
        : event.registration_url || event.source_url
    }
  };
});

// Só eventos com relevância direta para cripto
const eligible = scored.filter(item =>
  item.json.radar_score_reasons.includes("core_crypto_relevance")
);

// Maior pontuação primeiro
eligible.sort(
  (a, b) =>
    b.json.radar_score - a.json.radar_score
);

// Retorna até 3 eventos realmente relevantes
return eligible.slice(0, 3);

const items = $input.all().map(item => item.json);

// PT-BR simples para datas
function formatDate(dateString) {
  if (!dateString) return "";

  const date = new Date(`${dateString}T12:00:00`);

  return date.toLocaleDateString("pt-BR", {
    day: "2-digit",
    month: "short",
  });
}

function cleanAgendaHighlight(text) {
  if (!text) return "";

  // Remove o título inicial repetido
  return text
    .replace(/^Olhar da Agenda Crypto:\s*/i, "")
    .trim();
}

// Até 3 eventos
const e1 = items[0] || {};
const e2 = items[1] || {};
const e3 = items[2] || {};

// Contagens
const cities = new Set(
  items
    .map(event => event.city)
    .filter(Boolean)
);

const countries = new Set(
  items
    .map(event => event.country)
    .filter(Boolean)
);

// Tags/temas para descobrir tema recorrente
const topicCounts = {};

for (const event of items) {
  const topics = [
    ...(Array.isArray(event.tags) ? event.tags : []),
    event.category,
    event.event_type
  ].filter(Boolean);

  for (const topic of topics) {
    const normalized = String(topic).trim().toLowerCase();

    topicCounts[normalized] =
      (topicCounts[normalized] || 0) + 1;
  }
}

const trendingTopic =
  Object.entries(topicCounts)
    .sort((a, b) => b[1] - a[1])[0]?.[0] || "Cripto";

// Resumo provisório.
// Depois vamos substituir isso pela geração com IA.
const weeklySummary =
  items.length === 1
    ? `Nesta semana, o principal evento no radar da Agenda Crypto acontece em ${e1.city || e1.country || "LATAM"}.`
    : `Nesta semana, ${items.length} eventos se destacam no radar da Agenda Crypto, passando por ${Array.from(cities).join(", ")}.`;

// Insight provisório.
// Depois também vamos gerar com IA.
const agendaInsight =
  items[0]?.agenda_highlight
    ? cleanAgendaHighlight(items[0].agenda_highlight)
    : "A Agenda Crypto acompanha os movimentos dos eventos para identificar onde estão surgindo novas conexões, negócios e tendências no ecossistema.";

return [
  {
    json: {
      weekly_summary: weeklySummary,

      event_1_image: e1.image_url || "",
      event_1_name: e1.title || "",
      event_1_location:
        [e1.city, e1.country]
          .filter(Boolean)
          .join(", "),
      event_1_date: formatDate(e1.start_date),
      event_1_theme:
        e1.category ||
        e1.event_type ||
        "Cripto",
      event_1_insight:
        cleanAgendaHighlight(e1.agenda_highlight) ||
        e1.short_description ||
        "",
      event_1_url: e1.agenda_url || "",

      event_2_image: e2.image_url || "",
      event_2_name: e2.title || "",
      event_2_location:
        [e2.city, e2.country]
          .filter(Boolean)
          .join(", "),
      event_2_date: formatDate(e2.start_date),
      event_2_theme:
        e2.category ||
        e2.event_type ||
        "Cripto",
      event_2_insight:
        cleanAgendaHighlight(e2.agenda_highlight) ||
        e2.short_description ||
        "",
      event_2_url: e2.agenda_url || "",

      event_3_image: e3.image_url || "",
      event_3_name: e3.title || "",
      event_3_location:
        [e3.city, e3.country]
          .filter(Boolean)
          .join(", "),
      event_3_date: formatDate(e3.start_date),
      event_3_theme:
        e3.category ||
        e3.event_type ||
        "Cripto",
      event_3_insight:
        cleanAgendaHighlight(e3.agenda_highlight) ||
        e3.short_description ||
        "",
      event_3_url: e3.agenda_url || "",

      agenda_insight: agendaInsight,

      events_count: items.length,
      cities_count: cities.size,
      countries_count: countries.size,
      trending_topic: trendingTopic
    }
  }
];

